{
  "conditions": {
    "basis_identification": {
      "status": "pass",
      "note": "Each alleged incident is identified with a specific date or date range and attributed to a named actor (SHSS, HSS, Chief), with the basis for complaint stated explicitly (e.g., scrubs restriction, false statement to supervisor, schedule changes)."
    },
    "reasoning_traceability": {
      "status": "review",
      "note": "The record traces which claims were accepted (a, b, k-q), dismissed (g), and treated as background only (c-f, h-j), but does not articulate the reasoning for these triage decisions beyond procedural timeliness or counseling-stage requirements."
    },
    "cold_reviewer_clarity": {
      "status": "review",
      "note": "A later reviewer can identify the allegations and their dates, but lacks the full investigative findings, evidence evaluation, or agency's factual conclusions necessary to understand the basis for final dismissal, since the outcome text is removed."
    },
    "accountability_support": {
      "status": "gap",
      "note": "The record presents allegations and dates but omits the investigative findings, witness testimony summaries, and evidentiary assessment that would support the agency's conclusion that Complainant failed to prove discrimination."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "A clear chronological sequence is evident: April 15, 2018 (initial incident) through August 10, 2018 (end of alleged surveillance period), with intermediate dated incidents (May 1, June 19, June 21, June 25, July 10, 2018) providing traceable intervals."
    }
  },
  "remediation_note": "To achieve compliance, the record must restore the investigative findings section, summarizing witness testimony and evidence related to each accepted claim, and must include the agency's factual conclusions and reasoning for rejection of the discrimination allegation. A brief statement of the burden-shifting analysis applied would also strengthen accountability.",
  "finding": {
    "ai_function": "summarization",
    "condition_triggered": "accountability_support, reasoning_traceability, cold_reviewer_clarity",
    "compliant_version": "The full record must include: (1) a summary of investigation findings for each accepted claim (a, b, k-q), including witness testimony and documentary evidence examined; (2) the agency's factual conclusions on whether each alleged act occurred and whether it was discriminatory; (3) explicit reasoning for why the evidence was found insufficient to prove discrimination; and (4) a closure statement documenting the administrative judge withdrawal outcome and final agency decision authority."
  }
}
